CREATE OR REPLACE FUNCTION public.get_support_directory()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role public.user_role;
  v_tenant_id uuid;
  v_platform jsonb;
  v_tenant jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Support directory requires an active login.' using errcode = '42501';
  end if;

  v_role := safebus_private.current_user_role();
  v_tenant_id := safebus_private.current_tenant_id();

  if v_role is null then
    raise exception 'Support directory requires an active profile.' using errcode = '42501';
  end if;

  if v_role in ('platform_super_admin', 'tenant_admin') then
    select jsonb_build_object(
      'displayName', contact.display_name,
      'email', contact.email,
      'phone', contact.phone,
      'websiteUrl', contact.website_url,
      'supportHours', contact.support_hours,
      'instructions', contact.instructions,
      'updatedAt', contact.updated_at
    )
    into v_platform
    from public.platform_support_contacts contact
    where contact.id = true;
  end if;

  if v_role in ('tenant_admin', 'driver', 'guardian') and v_tenant_id is not null then
    select jsonb_build_object(
      'displayName', contact.display_name,
      'email', contact.email,
      'phone', contact.phone,
      'websiteUrl', contact.website_url,
      'supportHours', contact.support_hours,
      'instructions', contact.instructions,
      'updatedAt', contact.updated_at
    )
    into v_tenant
    from public.tenant_support_contacts contact
    where contact.tenant_id = v_tenant_id;
  end if;

  -- Platform contact details are published business support information. Put
  -- the fallback in the tenant slot so recipient apps expose only one contact.
  if v_role in ('driver', 'guardian') and v_tenant is null then
    select jsonb_build_object(
      'displayName', contact.display_name,
      'email', contact.email,
      'phone', contact.phone,
      'websiteUrl', contact.website_url,
      'supportHours', contact.support_hours,
      'instructions', contact.instructions,
      'updatedAt', contact.updated_at
    )
    into v_tenant
    from public.platform_support_contacts contact
    where contact.id = true;
  end if;

  return jsonb_build_object('platform', v_platform, 'tenant', v_tenant);
end;
$function$

CREATE OR REPLACE FUNCTION public.platform_finalize_tenant_invitation(p_auth_user_id uuid, p_tenant_name text, p_tenant_type text, p_school_name text, p_city text, p_admin_name text, p_admin_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant public.tenants%rowtype;
  v_auth_email text;
  v_tenant_name text := btrim(p_tenant_name);
  v_tenant_type text := btrim(p_tenant_type);
  v_admin_name text := btrim(p_admin_name);
  v_admin_email text := lower(btrim(p_admin_email));
begin
  if not safebus_private.is_platform_super_admin() then
    raise exception 'Only an active platform super administrator can finalize tenant onboarding.'
      using errcode = '42501';
  end if;
  perform safebus_private.enforce_mfa_if_required();
  perform safebus_private.enforce_recent_auth_for_sensitive_action();

  if p_auth_user_id is null
    or nullif(v_tenant_name, '') is null
    or nullif(v_admin_name, '') is null
    or nullif(v_admin_email, '') is null then
    raise exception 'Tenant and administrator details are required.' using errcode = '22023';
  end if;

  if v_tenant_type not in ('school', 'school_group', 'bus_contractor', 'demo')
    or length(v_tenant_name) > 200
    or length(v_admin_name) > 200
    or length(v_admin_email) > 320 then
    raise exception 'Tenant or administrator details are invalid.' using errcode = '22023';
  end if;

  select lower(u.email)
  into v_auth_email
  from auth.users u
  where u.id = p_auth_user_id;

  if v_auth_email is null or v_auth_email <> v_admin_email then
    raise exception 'The invited Auth account does not match the administrator email.'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.profiles p
    where p.id = p_auth_user_id or lower(p.email) = v_admin_email
  ) then
    raise exception 'The administrator email is already assigned to a SafeBus profile.'
      using errcode = '23505';
  end if;

  insert into public.tenants (name, type, status)
  values (v_tenant_name, v_tenant_type, 'active')
  returning * into v_tenant;

  insert into public.profiles (
    id, tenant_id, school_id, full_name, email, role, status
  ) values (
    p_auth_user_id, v_tenant.id, null, v_admin_name, v_admin_email,
    'tenant_admin', 'invited'
  );

  insert into public.tenant_onboarding_invitations (
    tenant_id, email, full_name, role, status,
    invited_profile_id, invited_by_profile_id, last_sent_at
  ) values (
    v_tenant.id, v_admin_email, v_admin_name, 'tenant_admin', 'pending',
    p_auth_user_id, auth.uid(), now()
  );

  return jsonb_build_object(
    'tenant', jsonb_build_object(
      'id', v_tenant.id,
      'name', v_tenant.name,
      'status', v_tenant.status
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tenant_support_contact(p_display_name text, p_email text, p_phone text, p_website_url text, p_support_hours text, p_instructions text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare v_tenant_id uuid;
begin
  if auth.uid() is null or safebus_private.current_user_role() is distinct from 'tenant_admin'::public.user_role then
    raise exception 'Only a tenant administrator can update tenant support.' using errcode = '42501';
  end if;
  v_tenant_id := safebus_private.current_tenant_id();
  if v_tenant_id is null then raise exception 'A tenant is required.' using errcode = '42501'; end if;
  perform safebus_private.enforce_mfa_if_required();
  perform safebus_private.enforce_recent_auth_for_sensitive_action();
  if nullif(trim(p_display_name), '') is null or length(trim(p_display_name)) > 120
    or nullif(trim(p_email), '') is null or length(trim(p_email)) > 320
    or trim(p_email) !~ '^[^@ ]+@[^@ ]+\.[^@ ]+$'
    or length(coalesce(trim(p_phone), '')) > 40
    or length(coalesce(trim(p_support_hours), '')) > 240
    or length(coalesce(trim(p_instructions), '')) > 1000
    or (nullif(trim(p_website_url), '') is not null and (length(trim(p_website_url)) > 500 or trim(p_website_url) !~ '^https://')) then
    raise exception 'Enter valid support contact details.' using errcode = '22023';
  end if;
  insert into public.tenant_support_contacts(tenant_id, display_name, email, phone, website_url, support_hours, instructions, updated_by)
  values (v_tenant_id, trim(p_display_name), lower(trim(p_email)), nullif(trim(p_phone), ''), nullif(trim(p_website_url), ''), nullif(trim(p_support_hours), ''), nullif(trim(p_instructions), ''), auth.uid())
  on conflict (tenant_id) do update set display_name = excluded.display_name, email = excluded.email,
    phone = excluded.phone, website_url = excluded.website_url, support_hours = excluded.support_hours,
    instructions = excluded.instructions, updated_by = auth.uid(), updated_at = now();
  perform safebus_private.phase5_write_audit_event(auth.uid(), 'tenant_support.updated', 'tenant', v_tenant_id, trim(p_display_name), '{}'::jsonb);
end $function$
